<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { platform, type Connector, type Mapping, type MappingField, type MappingPreview, type SourceField } from '../api/platform'
import { errorMessage } from '../utils/errors'

interface EnumPair { from: string; to: string }
interface Row extends Mapping { transformText: string; transformType: string; enumPairs: EnumPair[]; format: string; timezone: string; value: string; trim: boolean; caseMode: string; prefix: string; suffix: string; replaceFrom: string; replaceTo: string }
const id = String(useRoute().params.id)
const connector = ref<Connector | null>(null)
const rows = ref<Row[]>([])
const sample = ref<Record<string, unknown>[]>([])
const fields = ref<string[]>([])
const fieldDetails = ref<SourceField[]>([])
const saving = ref(false)
const previewing = ref(false)
const preview = ref<MappingPreview | null>(null)
const trackingSource = ref('')
const trackingRows = ref<Mapping[]>([])
const trackingTargets = ['external_event_id', 'event_type', 'location', 'event_time', 'longitude', 'latitude']
const targets = ref<MappingField[]>([])
const unmapped = computed(() => fieldDetails.value.filter(field => !rows.value.some(row => row.source_field === field.path)))
function makeRow(mapping: Mapping): Row { const config = mapping.transform || {}; const kind = String(config.type || ('values' in config ? 'enum' : 'default' in config ? 'default' : 'none')); const values = config.values as Record<string, string> | undefined; const replace = config.replace as {from?: string; to?: string} | undefined; return {...mapping, transformText:JSON.stringify(config), transformType:kind, enumPairs:Object.entries(values || {}).map(([from,to]) => ({from,to:String(to)})), format:String(config.format || ''), timezone:String(config.timezone || ''), value:String(config.value ?? config.default ?? ''), trim:Boolean(config.trim), caseMode:String(config.case || ''), prefix:String(config.prefix || ''), suffix:String(config.suffix || ''), replaceFrom:String(replace?.from || ''), replaceTo:String(replace?.to || '')} }
function add() { rows.value.push(makeRow({source_field:'', target_field:'', transform:{}, required:false})) }
function addTrackingField() { trackingRows.value.push({source_field:'', target_field:'', transform:{}, required:false}) }
async function saveTracking() { if (!trackingSource.value) { ElMessage.warning('请选择轨迹数组路径'); return } try { await platform.saveTrackingMapping(id, {source_field:trackingSource.value, fields:trackingRows.value.filter(row => row.source_field && row.target_field).map(row => ({...row, required:row.target_field === 'event_time' || row.required}))}); ElMessage.success('轨迹集合映射已保存') } catch (error) { ElMessage.error(errorMessage(error)) } }
async function loadSample() { try { const data = await platform.sampleConnector(id); sample.value = data.rows; fields.value = data.fields; fieldDetails.value = data.field_details || []; sessionStorage.setItem(`sample_${id}`, JSON.stringify(data)); if (!rows.value.length) await suggest() } catch (error) { ElMessage.error(errorMessage(error)) } }
async function suggest() { try { const matches = await platform.suggestMappings(fields.value.filter(field => fieldDetails.value.find(item => item.path === field)?.type !== 'array')); const used = new Set(rows.value.map(row => row.target_field)); for (const match of matches) { if (!used.has(match.target_field) && !rows.value.some(row => row.source_field === match.source_field)) { rows.value.push(makeRow({source_field:match.source_field, target_field:match.target_field, transform:{}, required:match.target_field === 'shipment_no'})); used.add(match.target_field) } } } catch (error) { ElMessage.error(errorMessage(error)) } }
function rowTransform(row: Row): Record<string, unknown> { if (row.transformType === 'enum') return {type:'enum', values:Object.fromEntries(row.enumPairs.filter(pair => pair.from).map(pair => [pair.from, pair.to]))}; if (row.transformType === 'datetime') return {type:'datetime', ...(row.format ? {format:row.format} : {}), ...(row.timezone ? {timezone:row.timezone} : {})}; if (row.transformType === 'default' || row.transformType === 'fixed' || row.transformType === 'constant') return {type:row.transformType, value:row.value}; if (row.transformType === 'string') return {type:'string', trim:row.trim, ...(row.caseMode ? {case:row.caseMode} : {}), ...(row.prefix ? {prefix:row.prefix} : {}), ...(row.suffix ? {suffix:row.suffix} : {}), ...(row.replaceFrom ? {replace:{from:row.replaceFrom, to:row.replaceTo}} : {})}; if (row.transformType === 'advanced') return JSON.parse(row.transformText) as Record<string, unknown>; if (row.transformType === 'number' || row.transformType === 'boolean') return {type:row.transformType}; return {} }
function currentMappings(): Mapping[] { return rows.value.filter(item => item.source_field && item.target_field).map(item => ({source_field:item.source_field, target_field:item.target_field, required:item.target_field === 'shipment_no' || item.required, transform:rowTransform(item)})) }
async function save() { saving.value = true; try { await platform.saveMappings(id, currentMappings()); ElMessage.success('字段映射已保存') } catch (error) { ElMessage.error(errorMessage(error)) } finally { saving.value = false } }
async function runPreview() { if (!sample.value.length) { ElMessage.warning('请先获取或上传样例数据'); return } previewing.value = true; try { preview.value = await platform.previewMapping(id, sample.value[0], currentMappings()) } catch (error) { ElMessage.error(errorMessage(error)) } finally { previewing.value = false } }
onMounted(async () => { try { const [loadedConnector, saved, metadata, tracking] = await Promise.all([platform.connector(id), platform.mappings(id), platform.mappingFields(), platform.trackingMapping(id)]); connector.value = loadedConnector; targets.value = metadata; rows.value = saved.map(item => makeRow({...item, required:item.target_field === 'shipment_no' || item.required})); trackingSource.value = tracking?.source_field || ''; trackingRows.value = tracking?.fields || []; const cached = sessionStorage.getItem(`sample_${id}`); if (cached) { const data = JSON.parse(cached); sample.value = data.rows; fields.value = data.fields; fieldDetails.value = data.field_details || []; if (!rows.value.length) await suggest() } } catch (error) { ElMessage.error(errorMessage(error)) } })
</script>

<template>
  <div class="page-heading"><div><p class="eyebrow">FIELD MAPPING</p><h1>{{ connector?.name }} · 字段映射</h1><p class="muted">将来源字段转换为平台统一运单字段</p></div><RouterLink :to="`/connectors/${id}`"><el-button>返回连接器</el-button></RouterLink></div>
  <div class="panel"><div class="actions"><el-button v-if="connector?.type === 'rest'" @click="loadSample">获取并识别样例</el-button><el-button @click="suggest">推荐映射</el-button><el-button @click="add">添加映射</el-button><el-button :loading="previewing" @click="runPreview">预览转换</el-button><el-button type="primary" :loading="saving" @click="save">保存映射</el-button></div>
    <p class="form-hint">已识别 {{ fieldDetails.length }} · 已映射 {{ rows.filter(row => row.source_field && row.target_field).length }} · 必填字段 {{ rows.some(row => row.target_field === 'shipment_no') ? '1/1' : '0/1' }} · 未映射 {{ unmapped.length }}</p>
    <p class="form-hint">运单号为必填字段。推荐匹配需人工确认；修改映射仅影响后续同步。</p>
    <el-table :data="rows" stripe><el-table-column label="来源字段" min-width="160"><template #default="scope"><el-input v-model="scope.row.source_field" placeholder="waybillNo" /></template></el-table-column><el-table-column label="目标字段" min-width="190"><template #default="scope"><el-select v-model="scope.row.target_field" filterable style="width:100%"><el-option v-for="target in targets" :key="target.name" :label="`${target.label} (${target.name}) · ${target.type}${target.required ? ' · 必填' : ''}`" :value="target.name" /></el-select></template></el-table-column><el-table-column label="转换方式" min-width="310"><template #default="scope"><el-select v-model="scope.row.transformType" style="width:100%"><el-option label="无转换" value="none" /><el-option label="枚举映射" value="enum" /><el-option label="日期时间" value="datetime" /><el-option label="数字" value="number" /><el-option label="布尔值" value="boolean" /><el-option label="字符串处理" value="string" /><el-option label="默认值" value="default" /><el-option label="固定值" value="fixed" /><el-option label="高级 JSON" value="advanced" /></el-select><div v-if="scope.row.transformType === 'enum'" style="margin-top:8px"><div v-for="(pair, index) in scope.row.enumPairs" :key="index" style="display:flex;gap:6px;margin-bottom:6px"><el-input v-model="pair.from" placeholder="来源值" /><el-select v-if="scope.row.target_field === 'status'" v-model="pair.to" placeholder="标准状态"><el-option v-for="option in targets.find(item => item.name === 'status')?.options || []" :key="option" :label="option" :value="option" /></el-select><el-input v-else v-model="pair.to" placeholder="目标值" /><el-button @click="scope.row.enumPairs.splice(index, 1)">×</el-button></div><el-button text @click="scope.row.enumPairs.push({from:'', to:''})">＋ 添加枚举值</el-button></div><div v-if="scope.row.transformType === 'datetime'" style="margin-top:8px"><el-input v-model="scope.row.format" placeholder="格式（留空自动识别）" /><el-input v-model="scope.row.timezone" placeholder="时区，如 Asia/Shanghai" style="margin-top:6px" /></div><el-input v-if="['default','fixed'].includes(scope.row.transformType)" v-model="scope.row.value" placeholder="值" style="margin-top:8px" /><div v-if="scope.row.transformType === 'string'" style="margin-top:8px"><el-checkbox v-model="scope.row.trim">去空格</el-checkbox><el-select v-model="scope.row.caseMode" placeholder="大小写"><el-option label="保持原样" value="" /><el-option label="大写" value="upper" /><el-option label="小写" value="lower" /></el-select><el-input v-model="scope.row.prefix" placeholder="前缀" style="margin-top:6px" /><el-input v-model="scope.row.suffix" placeholder="后缀" style="margin-top:6px" /><el-input v-model="scope.row.replaceFrom" placeholder="替换原文（可选）" style="margin-top:6px" /><el-input v-if="scope.row.replaceFrom" v-model="scope.row.replaceTo" placeholder="替换为" style="margin-top:6px" /></div><el-input v-if="scope.row.transformType === 'advanced'" v-model="scope.row.transformText" type="textarea" :rows="3" style="margin-top:8px" /></template></el-table-column><el-table-column label="必填" width="80"><template #default="scope"><el-switch v-model="scope.row.required" :disabled="scope.row.target_field === 'shipment_no'" /></template></el-table-column><el-table-column label="" width="75"><template #default="scope"><el-button text type="danger" @click="rows.splice(scope.$index, 1)">删除</el-button></template></el-table-column></el-table>
    <div v-if="fieldDetails.length" class="input-section"><strong>检测到的字段</strong><el-table :data="fieldDetails" size="small"><el-table-column prop="path" label="来源路径" /><el-table-column prop="type" label="类型" width="110" /><el-table-column label="样例值"><template #default="scope">{{ JSON.stringify(scope.row.sample_value) }}</template></el-table-column><el-table-column label="映射" width="220"><template #default="scope">{{ rows.find(row => row.source_field === scope.row.path)?.target_field || (scope.row.type === 'array' ? '数组字段：请配置子实体映射' : '未映射') }}</template></el-table-column></el-table></div>
    <div v-if="sample.length" class="input-section"><strong>原始样例数据</strong><pre>{{ JSON.stringify(sample[0], null, 2) }}</pre></div>
    <div v-if="preview" class="input-section"><strong>转换结果（未写入数据库）</strong><pre>{{ JSON.stringify(preview.transformed, null, 2) }}</pre><strong>校验结果</strong><div v-for="item in preview.validation" :key="`${item.field}-${item.message}`"><el-tag :type="item.level === 'error' ? 'danger' : item.level === 'warning' ? 'warning' : 'success'">{{ item.level }}</el-tag> {{ item.field }}：{{ item.message }}</div></div>
    <div class="input-section"><strong>轨迹数组映射</strong><p class="muted">将来源数组中的每个对象转换为轨迹事件；event_time 必填。</p><el-select v-model="trackingSource" filterable allow-create default-first-option placeholder="数组路径，如 journey.events" style="width:320px"><el-option v-for="field in fieldDetails.filter(item => item.type === 'array')" :key="field.path" :label="field.path" :value="field.path" /></el-select><el-table :data="trackingRows" stripe style="margin-top:10px"><el-table-column label="子字段路径"><template #default="scope"><el-input v-model="scope.row.source_field" placeholder="event.id 或 at" /></template></el-table-column><el-table-column label="轨迹字段"><template #default="scope"><el-select v-model="scope.row.target_field" style="width:100%"><el-option v-for="target in trackingTargets" :key="target" :label="target" :value="target" /></el-select></template></el-table-column><el-table-column label="必填" width="80"><template #default="scope"><el-switch v-model="scope.row.required" :disabled="scope.row.target_field === 'event_time'" /></template></el-table-column><el-table-column label="" width="75"><template #default="scope"><el-button text type="danger" @click="trackingRows.splice(scope.$index, 1)">删除</el-button></template></el-table-column></el-table><div class="actions" style="margin-top:10px"><el-button @click="addTrackingField">添加轨迹字段</el-button><el-button type="primary" plain @click="saveTracking">保存轨迹映射</el-button></div></div>
  </div>
</template>
